-- pipeline/outlet-succeeded
-- An outlet's feed was read: clears its error count.
--
-- Parameters, with the example values used to render this file:
--   $1 = null
--   $2 = 0
--   $3 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

update "outlets"
set "last_ok_at" = now(), "last_error" = $1, "consecutive_failures" = $2, "updated_at" = now()
where "outlets"."id" = $3;
